package com.franco.desco.adapter.in.web.crates;import io.swagger.v3.oas.annotations.media.Schema;import jakarta.validation.constraints.*;
public final class CrateRequests{private CrateRequests(){}@Schema(name="CrateReceiveRequest")public record Receive(@NotNull Long operativoVentaId,@NotNull@Positive Integer cantidad,@Size(max=80)String referencia,@Size(max=300)String observacion){}@Schema(name="CrateAssignRequest")public record Assign(@NotNull Long operativoSocioId,@NotNull@Positive Integer cantidad,@Size(max=300)String observacion){}@Schema(name="CrateReturnCratesRequest")public record ReturnCrates(@NotNull Long jabaAsignacionId,Long entregaSocioId,@NotNull@PositiveOrZero Integer cantidadLlenas,@NotNull@PositiveOrZero Integer cantidadVacias,@Size(max=300)String observacion){}@Schema(name="CrateAnnulRequest")public record Annul(@NotBlank@Pattern(regexp="ASIGNACION|DEVOLUCION")String tipo,@NotNull Long movimientoId,@NotBlank@Size(max=300)String motivo){} }
